-- GL accounts: create the chart of accounts, seed it, and link existing
-- PV GL lines (gl_details.code) and petty cash records (petty_cash."glCode")
-- to it with foreign keys.
--
-- Sources (also in prisma/data/gl-accounts-2024.json):
--   * Accounts: "Copy of Chart of Accounts-Masterlist -2024 1.csv" (Government
--     of Maldives Chart of Accounts), rows with Status = "Active" only
--     (789 accounts).
--   * Petty cash: "Petty Cash Expenditure Codes.pdf" (34 codes).
-- Cleaning rules: whitespace collapsed and trimmed; an empty English long text
-- falls back to the short text; Dhivehi texts that are empty or the
-- placeholder "X" are stored as NULL.
--
-- Safe on any database: existing codes that aren't in the chart get a
-- placeholder account (step 4) before the foreign keys are added, so this can't
-- fail half-applied on data we haven't inspected. Run scripts/gl-accounts.mjs
-- before and after deploying to see exactly what it did.

-- 1. CreateTable
CREATE TABLE "gl_accounts" (
    "code" INTEGER NOT NULL,
    "shortTextEn" TEXT NOT NULL,
    "longTextEn" TEXT NOT NULL,
    "shortTextDv" TEXT,
    "longTextDv" TEXT,
    "pettyCashAllowed" BOOLEAN NOT NULL DEFAULT false,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "gl_accounts_pkey" PRIMARY KEY ("code")
);

-- 2. Seed the chart of accounts

-- 3. Accounts petty cash may be charged to ("Petty Cash Expenditure Codes.pdf")
UPDATE "gl_accounts" SET "pettyCashAllowed" = true
WHERE "code" IN (221001, 221002, 221003, 221999, 222001, 222002, 222003, 222004, 222005, 222006, 222007, 222008, 222009, 222010, 222999, 223006, 223009, 223011, 223012, 223013, 223015, 223017, 223022, 223999, 224022, 225003, 226001, 226002, 226006, 226007, 226009, 226010, 226016, 226017);

-- 4. Placeholder accounts for any code already in use that isn't in the chart,
--    so the foreign keys below can always be added. Review these in
--    Settings > GL Accounts.
SELECT used."code",
       'Unlisted code',
       'Not in the 2024 Chart of Accounts - added to link existing records; review in Settings > GL Accounts',
       CURRENT_TIMESTAMP
FROM (
    SELECT "code" FROM "gl_details"
    UNION
    SELECT "glCode" FROM "petty_cash"
) AS used
WHERE NOT EXISTS (SELECT 1 FROM "gl_accounts" a WHERE a."code" = used."code");

-- 5. CreateIndex
CREATE INDEX "gl_details_code_idx" ON "gl_details"("code");

-- CreateIndex
CREATE INDEX "petty_cash_glCode_idx" ON "petty_cash"("glCode");

-- AddForeignKey
ALTER TABLE "gl_details" ADD CONSTRAINT "gl_details_code_fkey" FOREIGN KEY ("code") REFERENCES "gl_accounts"("code") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "petty_cash" ADD CONSTRAINT "petty_cash_glCode_fkey" FOREIGN KEY ("glCode") REFERENCES "gl_accounts"("code") ON DELETE RESTRICT ON UPDATE CASCADE;

-- 6. Grant the Administrator role the new GL account permissions (skipping any
--    it already holds). Users pick these up on their next sign-in.
UPDATE "roles"
SET "permissions" = "permissions" || ARRAY(
        SELECT p
        FROM unnest(ARRAY['glaccount:read', 'glaccount:create', 'glaccount:update', 'glaccount:delete']::text[]) AS p
        WHERE NOT (p = ANY ("roles"."permissions"))
    ),
    "updatedAt" = CURRENT_TIMESTAMP
WHERE "name" = 'Administrator';
